def transform(grid):
    h, w = len(grid), len(grid[0])
    groups = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8:
                groups.setdefault(c - r, []).append(r)

    segments = []
    for d, rows in groups.items():
        rows = sorted(set(rows))
        start = prev = rows[0]
        for r in rows[1:] + [None]:
            if r is None or r != prev + 1:
                segments.append((d, 2 * start + d, 2 * prev + d))
                if r is None:
                    break
                start = r
            prev = r

    out = [row[:] for row in grid]
    for i in range(len(segments)):
        d1, a1, b1 = segments[i]
        for j in range(i + 1, len(segments)):
            d2, a2, b2 = segments[j]
            if d1 == d2:
                continue
            u0, u1 = max(a1, a2), min(b1, b2)
            if u0 > u1:
                continue
            lo, hi = sorted((d1, d2))
            for r in range(h):
                for c in range(w):
                    if (grid[r][c] == 8 and lo < c - r < hi
                            and u0 <= r + c <= u1):
                        out[r][c] = 2
    return out
